// Le même état Luna — exprimé sur plusieurs canaux sensoriels en parallèle.
// Retirer un canal ne casse pas les autres.
// Le cerveau reconstruit la réalité depuis les canaux actifs.

export type SensoryChannel = "visual" | "audio" | "haptic" | "data" | "api";

export interface ChannelState {
  readonly channel:   SensoryChannel;
  readonly active:    boolean;
  readonly coherence: number;   // 0.0–1.0 — qualité du signal
}

// CanPerceive — au moins un canal actif avec cohérence > 0.7
export function canPerceive(channels: readonly ChannelState[]): boolean {
  return channels.some(c => c.active && c.coherence > 0.7);
}

// CanSubstitute — si un canal tombe, un autre peut porter l'état
export function canSubstitute(channels: readonly ChannelState[]): boolean {
  return channels.filter(c => c.active && c.coherence > 0.7).length > 1;
}

content.rust:
pub const CHANNELS: &[&str] = &["visual", "audio", "haptic", "data", "api"];

#[derive(Debug, Clone)]
pub struct ChannelState {
    pub channel:   String,
    pub active:    bool,
    pub coherence: f64,
}

/// CanPerceive — au moins un canal actif et cohérent
pub fn can_perceive(channels: &[ChannelState]) -> bool {
    channels.iter().any(|c| c.active && c.coherence > 0.7)
}

/// CanSubstitute — le cerveau peut basculer sur un canal alternatif
pub fn can_substitute(channels: &[ChannelState]) -> bool {
    channels.iter().filter(|c| c.active && c.coherence > 0.7).count() > 1
}
